import{_ as t,b as i,c as p,g as a}from"./chunks/framework.86O3EbG5.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"articles/books/nyip-course/1.md","filePath":"articles/books/nyip-course/1.md"}'),o={name:"articles/books/nyip-course/1.md"};function s(n,e,r,d,_,l){return i(),p("div",null,[...e[0]||(e[0]=[a('<p>《美国纽约摄影学院摄影教材》</p><p>这本书的第一章首先讲了一种摄影师的行为准则或称为摄影师的世界观。摄影应该先思考表达的主题，表达该主题所涉及的主体， 画面是否简洁，不会有干扰主体和主题的东西。</p><p>本书开篇设定了摄影师大脑的工作流程：</p><ol><li>确定主题</li><li>确定主体</li><li>简洁的画面</li></ol><p>之后章节中的技术，只是用于支撑上述工作流程的具体方法。</p><p>通过表达的主题（其实是一种情感）来推导光影的设计，主体的选择，为了突出主体，需要引导观看者的视线，这样就需要运用构图、光线等手法将主体钉入观看者的眼中。</p><h2 id="镜头" tabindex="-1">镜头</h2><p>镜头分为快慢两种，快慢和速度没有关系，是镜头可通过光的量，快镜头通过的光量大，慢镜头则相反</p><h2 id="光圈" tabindex="-1">光圈</h2><p>既然镜头是通过固定光量，需要调节光的通过量怎么办？这便是光圈的作用，光圈一般是 fx 这样的表示，x 是数字，数字越小、量越大。f2 是 f4 的两倍光量</p><h2 id="焦距" tabindex="-1">焦距</h2><p>焦距是镜头到投影板的距离，焦距越大，成像越大。一般有 35mm 50mm 85mm 等镜头。拍摄人物可能出现一种鼻子变大的效果。</p><h2 id="景深" tabindex="-1">景深</h2><p>光圈和焦距会影响景深。其光学原理是焦点处可以在底板上形成准确的光点，但非焦点处的光形成光圈或光斑，就会出现景深的效果，其实更像是一种散射吧。光圈变大，非焦点在底板上形成的光圈就更大了。</p><h2 id="快门" tabindex="-1">快门</h2><p>快门是控制光通过的时间，慢快门时间长、光通过时间久，于是就形成了车流线的效果。</p><h2 id="" tabindex="-1"></h2>',17)])])}const h=t(o,[["render",s]]);export{m as __pageData,h as default};
